import{z as s,x as o,o as r,c as p,q as t,j as B,D as A,d as a,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"表征工程","description":"","frontmatter":{"title":"表征工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-representation-engineering.md","filePath":"llm/xai-representation-engineering.md","lastUpdated":1791413859000}'),C={name:"llm/xai-representation-engineering.md"};function d(m,E,D,g,u,c){const n=o("Mermaid");return r(),p("div",null,[E[2]||(E[2]=t('<h1 id="表征工程" tabindex="-1">表征工程 <a class="header-anchor" href="#表征工程" aria-label="Permalink to &quot;表征工程&quot;">​</a></h1><div class="epigraph"><p>自下而上的解释翻字典找概念；自上而下的表征工程反过来：先点名概念，再去表征里找它的坐标，并且读得出、写得进。</p><footer>—— Zou et al., Representation Engineering: A Top-Down Approach to AI Transparency, 2023</footer></div><p><a href="/llm/xai-circuit-automation">上一课</a>自下而上拆通路：从激活出发，自动化地找边。本课换方向：先指定概念——诚实、谄媚、情感、危害——再在表征里定位它的坐标并读写，这就是 Zou 等人 2023 年提出的表征工程（representation engineering, RepE）。<a href="/llm/steering-vectors">Steering Vectors 课</a>已讲过加法向量本身的构造与失效；本课不重复加法，而是把读写扩展成方法学：概念坐标从哪来、读什么、写什么，以及它与无监督字典的分工。后两课的监控与训练引导都建立在这套读写上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自下而上的产出是一张十万条的特征表；安全工作需要的常常是<strong>点名找</strong>特定概念：欺骗在哪里、隐藏目标在哪里。监督式路线的问题化有三层：给定一个概念，怎么获得它的表征坐标——对比对、探针、字典检索各走一条路；读出的方向是否因果——线性探针高分不等于模型在用；读写会不会伤别的能力——概念的坐标与别的概念在残差流里未必正交。</p><p><span class="marginnote">「概念的坐标」翻译成大白话：把模型某一层的激活向量想成几千维空间里的一个点。如果「诚实」「欺骗」这类概念在这个空间里有稳定方向，就能像经纬度一样把它标出来——读数是问「当前这个点沿该方向投影多远」，写入是人为把点往该方向推或拉。</span></p><p>与字典路线的本质区别在先验：字典无监督，找到什么算什么，可能漏掉安全上最要紧的概念；RepE 有监督，坐标贴合需求，但标注先验会渗进方向里。两边的缺口互为镜像，这也是本课最后把二者接起来的理由。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>坐标的三来源。</strong> 其一，对比对均值差：正负输入在某层激活相减（<a href="/llm/steering-vectors">steering 课</a>的构造），快，但对词面污染敏感。其二，线性探针：在激活上监督地学一个读出方向；Azaria 与 Mitchell 2023 年用简单分类器读出模型「是否在说真话」的内部状态，Burns 等人 2023 年的 CCS 更进一步——不用标注，只要求方向在正反语句间保持一致，把「标注者的假设」关在门外。其三，SAE 字典检索：拿上一课验证过的特征当坐标库，按释义检索概念。</p><p><span class="marginnote">对比对均值差给个具体例子：收集 1000 条「诚实回答」和 1000 条「欺骗回答」，各取它们在同一层激活向量的平均，再相减——得到的向量就是「欺骗方向」的粗坐标。类比把两堆人脸照各求一张「平均脸」再做差：个体的差异被平均掉，剩下的是两类的系统性差别。它快，但如果正负例在措辞风格上系统性不同，学到的可能是风格方向而不是欺骗本身。</span></p><p><strong>读。</strong> 用坐标给任意输入打内部读数：监控、异常检测、评测的中间量——下一课的欺骗监控是主要应用。</p><p><strong>写与改道。</strong> 推理期加向量是可开关的写；把方向写进训练目标是永久性的写，<a href="/llm/circuit-breaker">Circuit Breaker 课</a>讲的表示重路由是其安全特例，本课不重复其损失细节。</p>',12)),(r(),B(l,null,{default:A(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONC%5B%22%E7%9B%AE%E6%A0%87%E6%A6%82%E5%BF%B5%22%5D%20--%3E%20PAIR%5B%22%E5%AF%B9%E6%AF%94%E5%AF%B9%E5%9D%87%E5%80%BC%E5%B7%AE%22%5D%0A%20%20CONC%20--%3E%20PROBE%5B%22%E7%BA%BF%E6%80%A7%E6%8E%A2%E9%92%88%20%2F%20CCS%22%5D%0A%20%20CONC%20--%3E%20DICT%5B%22SAE%20%E5%AD%97%E5%85%B8%E6%A3%80%E7%B4%A2%22%5D%0A%20%20PAIR%20--%3E%20V%5B%22%E8%A1%A8%E5%BE%81%E5%9D%90%E6%A0%87%20v%22%5D%0A%20%20PROBE%20--%3E%20V%0A%20%20DICT%20--%3E%20V%0A%20%20V%20--%3E%20READ%5B%22%E8%AF%BB%EF%BC%9A%E7%9B%91%E6%8E%A7%E4%B8%8E%E5%BC%82%E5%B8%B8%E6%A3%80%E6%B5%8B%22%5D%0A%20%20V%20--%3E%20WRITE%5B%22%E5%86%99%EF%BC%9A%E6%8E%A8%E7%90%86%E6%9C%9F%E5%8A%A0%E6%B3%95%E6%88%96%E8%AE%AD%E7%BB%83%E6%9C%9F%E5%86%99%E5%85%A5%22%5D%0A%20%20READ%20--%3E%20CHECK%7B%22%E5%B9%B2%E9%A2%84%E9%AA%8C%E6%94%B6%EF%BC%9A%E8%BD%AC%E5%90%91%E8%A1%8C%E4%B8%BA%E7%AC%A6%E5%90%88%E5%9D%90%E6%A0%87%E8%AF%AD%E4%B9%89%22%7D%0A%20%20WRITE%20--%3E%20CHECK%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("自上而下能成立，几何前提是残差流的"),e("strong",null,"近线性可加"),a("：概念在中等深度上有稳定、可分离的方向——Elhage 等人 2021 年的数学框架给出的视角，从注意力计算延伸到概念层坐标。但「可分离」不等于「在用」：读出方向可能是统计伴影，所以每个坐标都要过干预验收——转向行为与坐标语义一致才算数，这与第 2 课的特征验证是同一个闭环，只是概念先给定。")],-1)),E[5]||(E[5]=e("p",null,[a("监督与无监督的互补在机制上说得清：标注渗入的是"),e("strong",null,"方向的选择"),a("，不改变残差流本身的几何；字典检索不到目标概念，恰恰是「该概念在此层无线性坐标」的负证据。工程惯例是双路并行：RepE 坐标先上，字典检索复核；两条路给出不同方向时，先怀疑标注先验，再做对照干预仲裁。")],-1)),(r(),B(l,null,{default:A(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20REP%5B%22%E8%87%AA%E4%B8%8A%E8%80%8C%E4%B8%8B%20RepE%22%5D%20--%3E%20R1%5B%22%E5%9D%90%E6%A0%87%E8%B4%B4%E5%90%88%E9%9C%80%E6%B1%82%EF%BC%8C%E4%BD%86%E6%A0%87%E6%B3%A8%E5%85%88%E9%AA%8C%E4%BC%9A%E6%B8%97%E8%BF%9B%E6%96%B9%E5%90%91%22%5D%0A%20%20SAE%5B%22%E8%87%AA%E4%B8%8B%E8%80%8C%E4%B8%8A%E5%AD%97%E5%85%B8%22%5D%20--%3E%20S1%5B%22%E6%97%A0%E6%A0%87%E6%B3%A8%E5%85%88%E9%AA%8C%EF%BC%8C%E4%BD%86%E5%8F%AF%E8%83%BD%E6%BC%8F%E6%8E%89%E5%AE%89%E5%85%A8%E8%A6%81%E7%B4%A7%E7%9A%84%E6%A6%82%E5%BF%B5%22%5D%0A%20%20R1%20--%3E%20PAR%5B%22%E5%B7%A5%E7%A8%8B%E6%83%AF%E4%BE%8B%EF%BC%9A%E5%8F%8C%E8%B7%AF%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20S1%20--%3E%20PAR%0A%20%20PAR%20--%3E%20SAME%5B%22%E4%B8%A4%E8%B7%AF%E5%90%8C%E5%90%91%EF%BC%9A%E7%BD%AE%E4%BF%A1%E5%8D%87%E7%BA%A7%22%5D%0A%20%20PAR%20--%3E%20DIFF%5B%22%E4%B8%A4%E8%B7%AF%E5%BC%82%E5%90%91%EF%BC%9A%E5%85%88%E7%96%91%E6%A0%87%E6%B3%A8%E5%85%88%E9%AA%8C%EF%BC%8C%E5%86%8D%E5%AF%B9%E7%85%A7%E5%B9%B2%E9%A2%84%E4%BB%B2%E8%A3%81%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">「互为镜像」的直觉：RepE 保证「你点名的一定去找」，风险是找到的可能是你期待看到的方向（先验污染）；字典保证「找到的确实是模型在用的」，风险是你要的那个可能根本不在表里。两路同向时错误概率大幅下降，两路异向时等于免费得到一次报警——这就是双路并行比单路贵一点却值得的原因。</span></p><p><span class="marginnote">CCS 只要求读出方向满足一致性（正反语句上读数相反）与镜像性（方向取反后读数互换），不提供「哪个一致解是真的」的判据——无监督买来的是抗标注先验，付出去的是多重解的歧义。它适合做初筛，不适合单独做结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RepE 不是透视：读出的是「与概念统计相关的方向」，不是意图；分布一漂移，坐标的语义跟着漂。跨层要小心：中层读出的方向到浅层可能还没成形、到深层已写成 logits，读写通常锚在中层。安全场景另有一条硬边界：对可被监控的概念做对抗训练，模型可能学会在非线性可读的子空间表达同一内容——读写的可达性是当前方法的边界，不是模型的边界。概念清单本身也有政治学：什么算「谄媚」、什么算「诚实」，坐标的噪声里一半来自定义的噪声。</p><p><span class="marginnote">为什么重要：如果两家团队对「谄媚」的定义不同——一家只算「迎合用户错误说法」，另一家把「过度道歉」也算进去——各自标注学出的方向就会不同，读数不可比、结论互相打架。所以安全概念清单要先写清判定规则再谈坐标；这一步省掉，坐标噪声里就永远分不清「模型的问题」和「定义的问题」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RepE 自上而下：先点名概念，再取坐标、做读写；与字典路线的先验互为镜像。</li><li>坐标三来源：对比对均值差、探针与 CCS、验证过的 SAE 特征检索。</li><li>读出必须过干预验收：转向行为与坐标语义一致才算因果候选。</li><li>读写锚在中层；双路并行（监督 + 字典）互为负证据与仲裁。</li><li>出处：Zou et al., 2023；Burns et al., 2023（CCS）；Azaria &amp; Mitchell, 2023（内部状态读出）。</li></ul>',7))])}const R=s(C,[["render",d]]);export{F as __pageData,R as default};
